# SHOPBOT METRIC V4 — supervised head on frozen Vietnamese embeddings; Colab CPU is supported.
import base64,hashlib,io,zipfile,json,subprocess,sys
from pathlib import Path
PACK=base64.b64decode('')
EXPECTED='25797aab6848ab8edc6e0aab48fe7d4fe31e588dca824e28d8a535fb07ca672e'
assert hashlib.sha256(PACK).hexdigest()==EXPECTED
ROOT=Path('/content/shopbot_metric_v4_20261019_r1')
if ROOT.exists():
    assert (ROOT/'package.sha256').read_text()==EXPECTED, 'Different package at target; preserve existing files.'
ROOT.mkdir(parents=True,exist_ok=True)
with zipfile.ZipFile(io.BytesIO(PACK)) as archive:
    for item in archive.infolist():
        assert (ROOT/item.filename).resolve().is_relative_to(ROOT.resolve())
    archive.extractall(ROOT)
(ROOT/'package.sha256').write_text(EXPECTED)
print('METRIC V4 PACKAGE VERIFIED',EXPECTED,flush=True)
print(json.loads((ROOT/'data/manifest.json').read_text())['splits'],flush=True)
subprocess.run([sys.executable,'-m','pip','install','-q','transformers>=4.51,<6','pyvi','safetensors','scikit-learn','scipy','sentencepiece'],check=True)
subprocess.run([sys.executable,str(ROOT/'train_colab.py')],check=True)
OUT=Path('/content/shopbot_metric_v4_20261019_r1_artifacts.zip')
with zipfile.ZipFile(OUT,'w',zipfile.ZIP_DEFLATED) as bundle:
    for name in ['metric_controller.json','report.json','tutor-failures.jsonl']:
        bundle.write(ROOT/'outputs'/name,'outputs/'+name)
    bundle.write(ROOT/'data/manifest.json','data/manifest.json')
    bundle.write(ROOT/'train_colab.py','train_colab.py')
    bundle.write(ROOT/'metric_contract.py','metric_contract.py')
print('ARTIFACT',OUT.name,'BYTES',OUT.stat().st_size,'SHA256',hashlib.sha256(OUT.read_bytes()).hexdigest(),flush=True)
print((ROOT/'outputs/report.json').read_text(),flush=True)
from google.colab import files
files.download(str(OUT))
